// salsun2d_band_kernel.cpp
//
// Vitis kernel for Alveo U250 that runs SA-LSUN 2-D analysis, coefficient
// mask and synthesis of one frame band by band (overlap-save), with the
// band design salsun2d_hls_band generated by HDL Coder.
//
//   src       : one frame, SZY x SZX single, MATLAB column-major
//   params    : NPARAMS values packed by salsun2d_pack_params
//   stats_in  : standardization statistics mu (NDEC x NEST) followed by
//               sigma (NDEC x NEST), column-major, from the previous frames
//   dst       : reconstructed frame, same layout as src
//   stats_out : sums (NDEC x NEST) and sums of squares (NDEC x NEST) of the
//               estimator input channels over the blocks of this frame,
//               for the statistics of the next frame
//
// Bands of BAND block rows start at 0, BAND, 2*BAND, ...; the last band is
// moved up so that it ends at the last block row, and its sums are scaled
// by the share of rows it adds (as in salsun2d_band_frame.m). Each band
// is loaded with HALO block rows of circular context above and below.
// The parameters are read into on-chip memory once per call.
//
// Copyright (c) 2026, Shogo MURAMATSU
//
// All rights reserved.
//
